"""Financial ledger report with custom serializers for Decimal and datetime."""

import dataclasses
import decimal
from datetime import datetime

import reflex as rx

# ---------------------------------------------------------------------------
# Custom serializers.
#
# These serializers run when the state is synchronized to the browser, so the
# raw `decimal.Decimal` and `datetime.datetime` values stored in state are
# turned into the presentation strings the table expects.
# ---------------------------------------------------------------------------


@rx.serializer(overwrite=True)
def serialize_decimal(value: decimal.Decimal) -> str:
    """Render a `Decimal` as a 2-decimal-place currency string.

    Positive/zero values use ``$1,234.56`` style.  Negative values are
    rendered with a leading minus sign before the dollar sign using the
    absolute value, e.g. ``-$234.56``.
    """
    if value < 0:
        return f"-${abs(value):,.2f}"
    return f"${value:,.2f}"


@rx.serializer(overwrite=True)
def serialize_datetime(value: datetime) -> str:
    """Render a `datetime` as ``YYYY-MM-DD HH:MM`` (24-hour clock)."""
    return value.strftime("%Y-%m-%d %H:%M")


# ---------------------------------------------------------------------------
# Data model.
# ---------------------------------------------------------------------------


@dataclasses.dataclass
class LedgerEntry:
    description: str
    amount: decimal.Decimal
    timestamp: datetime


# ---------------------------------------------------------------------------
# State.
# ---------------------------------------------------------------------------


class State(rx.State):
    """The financial ledger application state."""

    entries: list[LedgerEntry] = [
        LedgerEntry(
            "Opening balance",
            decimal.Decimal("1000.00"),
            datetime(2024, 1, 1, 9, 0),
        ),
        LedgerEntry(
            "Grocery store",
            decimal.Decimal("-234.56"),
            datetime(2024, 1, 2, 14, 30),
        ),
        LedgerEntry(
            "Salary",
            decimal.Decimal("2500.00"),
            datetime(2024, 1, 5, 8, 0),
        ),
        LedgerEntry(
            "Electric bill",
            decimal.Decimal("-89.99"),
            datetime(2024, 1, 10, 16, 45),
        ),
    ]

    new_description: str = ""
    new_amount: str = ""

    @rx.var
    def rows(self) -> list[dict]:
        """Return one row per entry with the running balance included.

        The running balance is computed from the entries in listed order, and
        is itself a `Decimal` so the custom serializer turns it into a
        currency string for the browser.
        """
        balance = decimal.Decimal("0")
        result: list[dict] = []
        for entry in self.entries:
            balance += entry.amount
            result.append(
                {
                    "description": entry.description,
                    "amount": entry.amount,
                    "timestamp": entry.timestamp,
                    "balance": balance,
                }
            )
        return result

    @rx.var
    def total_credits(self) -> decimal.Decimal:
        """Sum of all positive amounts (the credits)."""
        return sum(
            (entry.amount for entry in self.entries if entry.amount > 0),
            decimal.Decimal("0"),
        )

    @rx.var
    def total_debits(self) -> decimal.Decimal:
        """Sum of the absolute values of all negative amounts (the debits)."""
        return sum(
            (abs(entry.amount) for entry in self.entries if entry.amount < 0),
            decimal.Decimal("0"),
        )

    @rx.var
    def net_balance(self) -> decimal.Decimal:
        """Sum of every amount in the ledger."""
        return sum(
            (entry.amount for entry in self.entries),
            decimal.Decimal("0"),
        )

    @rx.event
    def set_new_description(self, value: str) -> None:
        self.new_description = value

    @rx.event
    def set_new_amount(self, value: str) -> None:
        self.new_amount = value

    @rx.event
    def add_entry(self) -> None:
        """Append a new ledger entry using the input values."""
        description = self.new_description.strip()
        amount_text = self.new_amount.strip()
        if not description or not amount_text:
            return
        try:
            amount = decimal.Decimal(amount_text)
        except decimal.InvalidOperation:
            return
        self.entries.append(
            LedgerEntry(
                description=description,
                amount=amount,
                timestamp=datetime.now(),
            )
        )
        self.new_description = ""
        self.new_amount = ""


# ---------------------------------------------------------------------------
# UI components.
# ---------------------------------------------------------------------------


def _ledger_row(row: dict) -> rx.Component:
    return rx.table.row(
        rx.table.cell(row["description"]),
        rx.table.cell(row["amount"]),
        rx.table.cell(row["timestamp"]),
        rx.table.cell(row["balance"]),
    )


def _ledger_table() -> rx.Component:
    return rx.table.root(
        rx.table.header(
            rx.table.row(
                rx.table.column_header_cell("Description"),
                rx.table.column_header_cell("Amount"),
                rx.table.column_header_cell("Timestamp"),
                rx.table.column_header_cell("Balance"),
            ),
        ),
        rx.table.body(
            rx.foreach(State.rows, _ledger_row),
        ),
        variant="surface",
        size="3",
        width="100%",
    )


def _add_entry_form() -> rx.Component:
    return rx.form(
        rx.hstack(
            rx.input(
                placeholder="Description",
                value=State.new_description,
                on_change=State.set_new_description,
                width="100%",
            ),
            rx.input(
                placeholder="Amount (e.g. 50.25 or -12.00)",
                value=State.new_amount,
                on_change=State.set_new_amount,
                width="100%",
            ),
            rx.button("Add entry", type="submit"),
            spacing="3",
            align="center",
            width="100%",
        ),
        on_submit=State.add_entry,
        width="100%",
    )


def _totals_panel() -> rx.Component:
    return rx.hstack(
        rx.card(
            rx.vstack(
                rx.text("Total credits", size="2", color="gray"),
                rx.text(State.total_credits, size="6", weight="bold"),
                spacing="1",
                align="start",
            ),
        ),
        rx.card(
            rx.vstack(
                rx.text("Total debits", size="2", color="gray"),
                rx.text(State.total_debits, size="6", weight="bold"),
                spacing="1",
                align="start",
            ),
        ),
        rx.card(
            rx.vstack(
                rx.text("Net balance", size="2", color="gray"),
                rx.text(State.net_balance, size="6", weight="bold"),
                spacing="1",
                align="start",
            ),
        ),
        spacing="4",
        width="100%",
    )


def index() -> rx.Component:
    return rx.container(
        rx.vstack(
            rx.heading("Financial Ledger Report", size="9"),
            rx.text(
                "Live ledger with running balance and totals. "
                "All amounts and timestamps are formatted by custom Reflex "
                "serializers on the way to the browser.",
                size="3",
                color="gray",
            ),
            rx.box(
                _ledger_table(),
                width="100%",
            ),
            _totals_panel(),
            rx.box(
                rx.vstack(
                    rx.heading("Add a new entry", size="4"),
                    _add_entry_form(),
                    spacing="3",
                    align="stretch",
                    width="100%",
                ),
                width="100%",
            ),
            spacing="6",
            width="100%",
            max_width="900px",
            padding_y="6",
        ),
        size="3",
    )


app = rx.App(theme=rx.theme(appearance="light", accent_color="indigo", radius="medium"))
app.add_page(index)

